import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all code-block styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createCodeStyles = (t: PdfcnTheme) => {
  const { spacing, borderRadius, typography } = t.primitives;
  return StyleSheet.create({
    code: {
      color: t.colors.foreground,
      fontFamily: "Courier",
      fontSize: typography.xs,
      lineHeight: 1.45,
    },
    container: {
      backgroundColor: t.colors.muted,
      borderColor: t.colors.border,
      borderRadius: borderRadius.sm,
      borderStyle: "solid",
      borderWidth: 0.5,
      marginBottom: t.spacing.componentGap,
      padding: spacing[3],
    },
    ellipsis: { color: t.colors.mutedForeground },
    title: {
      borderBottomColor: t.colors.border,
      borderBottomStyle: "solid",
      borderBottomWidth: 0.5,
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      letterSpacing: 0.5,
      marginBottom: spacing[2],
      paddingBottom: spacing[1],
    },
    tokenComment: { color: t.colors.mutedForeground },
    tokenKeyword: { color: t.colors.accent },
    tokenNumber: { color: t.colors.warning },
    tokenString: { color: t.colors.success },
  });
};

import { Text as FormeText } from "@formepdf/react";

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/components/pdf/theme-provider";
import {
  View,
  Text as PDFText,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import { resolveColor } from "@/lib/resolve-color";

import { createCodeStyles } from "./code.styles";
import type { CodeProps } from "./code.types";
import { detectLanguage, tokenizeLine } from "./code.utils";
import type { CodeTokenType } from "./code.utils";

export const Code = ({
  code,
  title,
  language,
  maxLines,
  accentColor,
  style,
}: CodeProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createCodeStyles(theme), [theme]);

  const allLines = code.split("\n");
  const truncated = maxLines !== undefined && allLines.length > maxLines;
  const lines = truncated ? allLines.slice(0, maxLines) : allLines;

  const containerStyles: Style[] = [styles.container];
  if (accentColor) {
    containerStyles.push({
      borderLeftColor: resolveColor(accentColor, theme.colors),
      borderLeftWidth: 2,
    });
  }
  if (style) {
    containerStyles.push(style);
  }

  const lang = language ?? detectLanguage(title);
  const tokenStyle: Record<CodeTokenType, Style | undefined> = {
    comment: styles.tokenComment,
    keyword: styles.tokenKeyword,
    number: styles.tokenNumber,
    plain: undefined,
    string: styles.tokenString,
  };

  return (
    <View style={containerStyles}>
      {title ? <PDFText style={styles.title}>{title}</PDFText> : null}
      {lines.map((line, i) => (
        <PDFText key={`${i}-${line.length}`} style={styles.code}>
          {line.length === 0
            ? " "
            : tokenizeLine(line, lang).map((token, j) =>
                token.type === "plain" ? (
                  token.text
                ) : (
                  // Raw <Text> required: Forme only produces styled runs from
                  // elements whose type it recognises (Text, Strong, Em…).
                  <FormeText key={`${i}-${j}`} style={tokenStyle[token.type]}>
                    {token.text}
                  </FormeText>
                )
              )}
        </PDFText>
      ))}
      {truncated ? (
        <PDFText style={[styles.code, styles.ellipsis]}>…</PDFText>
      ) : null}
    </View>
  );
};

import type { Style } from "@/lib/pdf-primitives";

import type { CodeLanguage } from "./code.utils";

/**
 * Monospaced code snippet on a muted filled background with rounded corners.
 * Props - `code` | `title` | `language` | `maxLines` | `accentColor` | `renderingBase` | `style`
 * @see {@link CodeProps}
 */
export interface CodeProps {
  /** Source text. Line breaks are preserved; long lines wrap within the block. */
  code: string;
  /** Small label bar above the code (filename, language, or command). */
  title?: string;
  /**
   * Syntax highlighting language. When omitted, the language is inferred from
   * a filename-like `title` (e.g. `"app.ts"`); plain text is used if unknown.
   */
  language?: CodeLanguage;
  /** Truncate the snippet after this many lines, adding an ellipsis line. */
  maxLines?: number;
  /**
   * Accent color for a left rule on the block. Omit for a plain filled block.
   */
  accentColor?: string;
  renderingBase?: "takumi" | "forme";
  style?: Style;
}

/** Language identifiers accepted by the Code component's `language` prop. */
export type CodeLanguage =
  | "bash"
  | "javascript"
  | "js"
  | "json"
  | "jsx"
  | "py"
  | "python"
  | "sh"
  | "shell"
  | "ts"
  | "tsx"
  | "typescript"
  | "zsh";

/** Visual category a code token is painted with. */
export type CodeTokenType =
  | "comment"
  | "keyword"
  | "number"
  | "plain"
  | "string";

export interface CodeToken {
  text: string;
  type: CodeTokenType;
}

interface LanguageConfig {
  /** Patterns that start a comment (matched to end of line). */
  comments: string[];
  /** Exact words painted as keywords (also covers literals and commands). */
  keywords: string[];
}

const STRING_RE = [
  String.raw`"(?:[^"\\\n]|\\.)*"`,
  String.raw`'(?:[^'\\\n]|\\.)*'`,
  "`(?:[^`\\\\\n]|\\\\.)*`",
].join("|");
const NUMBER_RE = String.raw`\b\d[\d_]*(?:\.[\d_]+)?\b`;
const SLASH_COMMENT = String.raw`\/\/[^\n]*|\/\*[^\n]*?\*\/`;
const HASH_COMMENT = String.raw`#[^\n]*`;

const C_KEYWORDS = [
  "async",
  "await",
  "break",
  "case",
  "catch",
  "class",
  "const",
  "continue",
  "debugger",
  "default",
  "delete",
  "do",
  "else",
  "export",
  "extends",
  "false",
  "finally",
  "for",
  "from",
  "function",
  "get",
  "if",
  "import",
  "in",
  "instanceof",
  "let",
  "new",
  "null",
  "of",
  "return",
  "set",
  "static",
  "super",
  "switch",
  "this",
  "throw",
  "true",
  "try",
  "typeof",
  "undefined",
  "var",
  "void",
  "while",
  "yield",
];

const PY_KEYWORDS = [
  "False",
  "None",
  "True",
  "and",
  "as",
  "assert",
  "async",
  "await",
  "break",
  "class",
  "continue",
  "def",
  "del",
  "elif",
  "else",
  "except",
  "finally",
  "for",
  "from",
  "global",
  "if",
  "import",
  "in",
  "is",
  "lambda",
  "nonlocal",
  "not",
  "or",
  "pass",
  "print",
  "raise",
  "return",
  "try",
  "while",
  "with",
  "yield",
];

const SH_KEYWORDS = [
  "alias",
  "apt",
  "brew",
  "case",
  "cd",
  "chmod",
  "cp",
  "curl",
  "docker",
  "do",
  "done",
  "echo",
  "elif",
  "else",
  "esac",
  "export",
  "fi",
  "for",
  "function",
  "git",
  "if",
  "in",
  "local",
  "ls",
  "mkdir",
  "mv",
  "npm",
  "npx",
  "pnpm",
  "printf",
  "read",
  "rm",
  "set",
  "source",
  "sudo",
  "then",
  "unset",
  "wget",
  "while",
  "yarn",
];

const normalizeLanguage = (language?: string): string => {
  switch (language?.toLowerCase()) {
    case "javascript":
    case "js":
    case "jsx":
    case "ts":
    case "tsx":
    case "typescript": {
      return "clike";
    }
    case "py":
    case "python": {
      return "python";
    }
    case "json": {
      return "json";
    }
    case "bash":
    case "sh":
    case "shell":
    case "zsh": {
      return "shell";
    }
    default: {
      return "";
    }
  }
};

const LANG_CONFIGS: Record<string, LanguageConfig> = {
  clike: { comments: [SLASH_COMMENT], keywords: C_KEYWORDS },
  json: { comments: [], keywords: ["false", "null", "true"] },
  python: { comments: [HASH_COMMENT], keywords: PY_KEYWORDS },
  shell: { comments: [HASH_COMMENT], keywords: SH_KEYWORDS },
};

/** Infers a language hint from a title/filename extension (`"app.ts"` → `"ts"`). */
export const detectLanguage = (title?: string): string | undefined => {
  const match = title
    ?.trim()
    .split(/\s+/)[0]
    ?.match(/\.([a-z]+)$/i);
  return match?.[1]?.toLowerCase();
};

/** Splits one line of source into typed tokens for inline highlighting. */
export const tokenizeLine = (line: string, language?: string): CodeToken[] => {
  const cfg = LANG_CONFIGS[normalizeLanguage(language)];
  if (!cfg) {
    return [{ text: line, type: "plain" }];
  }
  const keywordRe = `\\b(?:${cfg.keywords.join("|")})\\b`;
  const parts = [...cfg.comments, STRING_RE, NUMBER_RE, keywordRe];
  const re = new RegExp(`(${parts.join(")|(")})`, "g");
  const types: CodeTokenType[] = [
    ...cfg.comments.map(() => "comment" as const),
    "string",
    "number",
    "keyword",
  ];
  const tokens: CodeToken[] = [];
  let cursor = 0;
  for (const match of line.matchAll(re)) {
    const index = match.index ?? 0;
    if (index > cursor) {
      tokens.push({ text: line.slice(cursor, index), type: "plain" });
    }
    const group = match.slice(1).findIndex((g) => g !== undefined);
    tokens.push({ text: match[0], type: types[group] ?? "plain" });
    cursor = index + match[0].length;
  }
  if (cursor < line.length) {
    tokens.push({ text: line.slice(cursor), type: "plain" });
  }
  return tokens;
};
